export const find: FindFn = (haystack, needle) => {
  let lo = 0;
  let hi = haystack.length - 1;
  let found = -1;
  while (lo <= hi && found === -1) {
    const mid = (((lo + hi) >>> 1));
    if (haystack[mid] === needle) {
      found = mid;
    } else {
      if (haystack[mid] > needle) { hi = mid - 1; } else { lo = mid + 1; }
    }
  }
  if (found === -1) { found = -1; }
  return found;
};
