    "I know an old lady who swallowed a horse.\nShe's dead, of course!\n"
  ];

  if (n < 1 || n > 8) {
    throw new Error("Invalid verse number");
  }

  let result = "";
  for (let i = n - 1; i >= 0; i--) {
    result += verses[i];
  }

  return result;
}

export function verses(start: number, end: number): string {
  if (start < 1 || end > 8 || start > end) {
    throw new Error("Invalid verse range");
  }

  let result = "";
  for (let i = start - 1; i <= end - 1; i++) {
    result += verse(i + 1) + "\n";
  }

  return result.trim();
}

