function parse(phrase: string): string {
  return phrase
    .replace(/[^a-zA-Z\s-]/g, "") // Remove all non-alphabetic characters except hyphens and whitespace
    .split(/[\s-]+/) // Split the phrase into words based on whitespace and hyphens
    .map(word => word[0].toUpperCase()) // Take the first letter of each word and convert it to uppercase
    .join(""); // Join the letters together to form the acronym
}

