import { Queue } from '@datastructures-js/queue';

export type FamilyTree = Record<string, string[]>;

export function degreesOfSeparation(familyTree: FamilyTree, personA: string, personB: string): number {
  if (personA === personB) return 0;

  const visited = new Set<string>();
  const queue = new Queue<{ person: string, distance: number }>();
  queue.enqueue({ person: personA, distance: 0 });

  while (!queue.isEmpty()) {
    const { person, distance } = queue.dequeue();

    if (visited.has(person)) continue;
    visited.add(person);

    for (const child of familyTree[person] || []) {
      if (child === personB) return distance + 1;
      queue.enqueue({ person: child, distance: distance + 1 });
    }
  }

  return -1; // No known relationship
}

